const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const notes=new URLSearchParams(location.search).has('notes'), channel=new BroadcastChannel('stellar-pitch-v1');
let state={index:0,total:0,elapsed:0,running:false,auto:false,stamp:Date.now()},last=Date.now(),lastSeen=0;
try{const saved=JSON.parse(localStorage.getItem('stellar-state'));if(saved&&Number.isInteger(saved.index)&&saved.index>=0&&saved.index<slides.length)state={...saved,running:false,stamp:Date.now()}}catch{}
const clock=ms=>{const s=Math.floor(Math.max(0,ms)/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`};
function publish(){state.stamp=Date.now();channel.postMessage({type:'state',state});localStorage.setItem('stellar-state',JSON.stringify(state))}
function render(){const s=slides[state.index];$('#counter').textContent=`${String(state.index+1).padStart(2,'0')} / 18`;$('#section').textContent=s.section;$('#prev').disabled=state.index===0;$('#next').disabled=state.index===17;$('#progress').style.width=`${(state.index+1)/18*100}%`;
if(notes){$('#script').innerHTML=`<span class="eyebrow">${esc(s.section)} · Notas originales de la sección</span><h1>${esc(s.title)}</h1><p class="sub">En pantalla: ${esc(s.sub)}</p><div>${esc(s.notes.replace(/\*\*/g,'').replace(/\*\[/g,'['))}</div><p class="sub">Sigue: ${esc(slides[state.index+1]?.title||'Fin de la charla')}</p>`;$('#index').innerHTML=slides.map((x,i)=>`<button class="${i===state.index?'active':''}" data-go="${i}" title="${esc(x.title)}">${i+1}</button>`).join('');return}
let visual='';if(s.kind==='hero')visual=`<div class="hero"><div><div class="eyebrow">Charla 03 · UMSA · 29 octubre 2026</div><h1>${s.title}</h1><p class="sub">${s.sub}</p><div class="tag">AGENTES EN LA RED STELLAR</div><p class="sub">Blockchain sin misterio.</p></div><div class="poster"><img src="assets/event.png" alt="Cartel del evento Agentes IA + Blockchain Halloween"></div></div>`;
else{let content='';if(s.kind==='code')content=`<pre>${s.items.map((x,i)=>`<span style="--i:${i}">${esc(x)||' '}</span>`).join('')}</pre>`;else if(s.kind==='table')content=`<table>${s.items.map(x=>`<tr>${x.split('|').map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</table>`;else if(s.kind==='network')content=s.items.slice(0,4).map((x,i)=>`<div class="node" style="--i:${i}">${esc(x)}</div>`).join('<span>↔</span>')+`<p>${s.items[4]}</p>`;else if(s.kind==='closing')content=s.items.map(x=>`<a href="https://${x}" target="_blank" rel="noopener">${x} ↗</a>`).join('')+'<p class="footnote">Stellar es una marca de Stellar Development Foundation. Presentación comunitaria independiente.</p>';else content=s.items.map((x,i)=>{const [a,b]=x.split('|');return `<div class="tile" style="--i:${i}"><strong>${esc(a)}</strong><small>${esc(b||'')}</small></div>`}).join('');visual=`<div class="eyebrow">${esc(s.section)} / Agentes en la red Stellar</div><h1>${esc(s.title)}</h1><p class="sub">${esc(s.sub)}</p><div class="visual ${s.kind}">${content}</div>${state.index===9?'<p class="footnote">* Sin congestión. Soroban añade tarifas de recursos. No es una cotización en USD.</p>':''}`}
$('#stage').innerHTML=`<article class="slide">${visual}</article>`}
function tickUI(){const s=slides[state.index];$('#play').textContent=state.running?'Pausar':'Iniciar / continuar';$('#auto').classList.toggle('active',state.auto);$('#time').textContent=`${clock(state.total)} / 30:00`;if(notes){$('#automatic').checked=state.auto;$('#connection').textContent=Date.now()-lastSeen<2500?'● Presentación conectada en este navegador':'Abre la presentación en otra pestaña del mismo navegador y dirección.';$('#clocks').innerHTML=`<small>ESTA DIAPOSITIVA / PREVISTO</small><span class="${state.elapsed>s.seconds*1000?'late':''}">${clock(state.elapsed)} / ${clock(s.seconds*1000)}</span><small>TOTAL / PREVISTO</small>${clock(state.total)} / 30:00`}}
function command(type,index){if(notes){channel.postMessage({type,index});return}if(type==='next'||type==='prev'||type==='go'){const next=type==='go'?index:state.index+(type==='next'?1:-1);if(next<0||next>=slides.length)return;state.index=next;state.elapsed=0;render()}if(type==='play')state.running=!state.running;if(type==='auto')state.auto=!state.auto;if(type==='reset'){state={index:0,total:0,elapsed:0,running:false,auto:false,stamp:Date.now()};render()}last=Date.now();publish();tickUI()}
channel.onmessage=e=>{if(e.data.type==='state'&&notes){const changed=state.index!==e.data.state.index;state=e.data.state;lastSeen=Date.now();if(changed)render();tickUI()}else if(e.data.type==='hello'&&!notes)publish();else if(!notes&&['next','prev','go','play','auto','reset'].includes(e.data.type))command(e.data.type,e.data.index)};
$('#notes').onclick=()=>window.open('?notes','stellar-notes');$('#prev').onclick=()=>command('prev');$('#next').onclick=()=>command('next');$('#play').onclick=()=>command('play');$('#auto').onclick=()=>command('auto');$('#reset').onclick=()=>command('reset');$('#automatic').onchange=()=>command('auto');$('#index').onclick=e=>{const b=e.target.closest('[data-go]');if(b)command('go',Number(b.dataset.go))};$('#full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{}};
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;const k=e.key.toLowerCase(),m={arrowright:'next',pagedown:'next',arrowleft:'prev',pageup:'prev',' ':'play',a:'auto',t:'reset'};if(m[k]){e.preventDefault();command(m[k])}if(k==='p')$('#notes').click();if(k==='f')$('#full').click()});
if(notes){document.body.classList.add('notes-mode');$('#presenter').hidden=false;$('#notes').textContent='Diapositivas ↗';$('#notes').onclick=()=>window.open('./','stellar-deck');fetch('libreto.md').then(r=>r.text()).then(t=>$('#original').textContent=t);channel.postMessage({type:'hello'})}
render();tickUI();setInterval(()=>{const now=Date.now();if(!notes){if(state.running){let delta=now-last;state.total+=delta;state.elapsed+=delta;if(state.auto){while(state.elapsed>=slides[state.index].seconds*1000){if(state.index===17){state.running=false;break}state.elapsed-=slides[state.index].seconds*1000;state.index++;render()}}}publish()}last=now;tickUI()},250);
